// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // General rule: a non-owner can never change ownership; ownership only
        // changes when the current owner calls setOwner. The buggy contract
        // lets any non-owner succeed (ok == true) and blocks the owner.
        assertTrue(!ok, "non-owner must not be able to set the owner");
    }
}
